import requests

def get_channel_messages(channel):
    response = requests.get(f'https://slack.com/api/conversations.history?channel={channel}&limit=1000')
    data = response.json()
    messages = data['messages']
    return messages

def count_user_messages(messages, user):
    count = 0
    for message in messages:
        if message['user'] == user:
            count += 1
    return count

def sort_users_by_message_count(users, channel):
    messages = get_channel_messages(channel)
    user_message_counts = {}
    for user in users:
        user_message_counts[user] = count_user_messages(messages, user)
    sorted_users = sorted(user_message_counts, key=lambda x: (-user_message_counts[x], x))
    return sorted_users

def send_direct_message(recipient, body):
    response = requests.post(f'https://slack.com/api/chat.postMessage?channel=@{recipient}&text={body}')
    return response.json()

def main():
    channel = 'general'
    users = ['Alice', 'Bob', 'Charlie', 'Eve']
    sorted_users = sort_users_by_message_count(users, channel)
    for i, user in enumerate(sorted_users):
        body = f'Congrats on being the {i+1}-th most active user!'
        send_direct_message(user, body)

main()
